package am.zzws.admin;

import org.json.*;

/** Deliberately synthetic in-memory fixture. Never reaches a network or real order. */
final class DemoStore {
 final JSONArray orders=new JSONArray(),events=new JSONArray();int nextEvent=1;
 DemoStore(){try{for(int i=1;i<=6;i++){JSONObject order=new JSONObject().put("id",String.format("00000000-0000-4000-8000-%012d",i)).put("number",900000000+i).put("revision",1).put("status",i==1?"new":i==2?"confirmed":"in_progress").put("created","2026-10-28T08:00:00Z").put("updated","2026-10-28T08:00:00Z").put("comment","").put("customer",new JSONObject().put("client","ՓՈՐՁ ZZWS — գործընկեր "+i)).put("delivery",new JSONObject().put("organization","Փորձնական գործընկեր "+i).put("address","Փորձնական հասցե "+i).put("contact","Փորձնական կոնտակտ").put("method",i%2==0?"Ինքնաառաքում":"Առաքում")).put("lines",new JSONArray().put(new JSONObject().put("articul","TEST-00"+i).put("name","Փորձնական ապրանք "+i).put("qty",i).put("unitPrice",1000))).put("total",i*1000);if(i==2)order.put("created_by",new JSONObject().put("id","00000000-0000-4000-8000-000000000100").put("name","Փորձնական աշխատակից").put("login","demo-manager"));orders.put(order);record(order,"order.created","Ստեղծվել է փորձնական պատվեր");}}catch(JSONException e){throw new IllegalStateException(e);}}
 JSONObject find(String id)throws Exception{for(int i=0;i<orders.length();i++){JSONObject o=orders.getJSONObject(i);if(id.equals(o.getString("id")))return o;}throw new Exception("Պատվերը չի գտնվել");}
 JSONArray list(String search,String status)throws Exception{JSONArray out=new JSONArray();String q=search.toLowerCase();for(int i=0;i<orders.length();i++){JSONObject o=orders.getJSONObject(i);if((status.isEmpty()||status.equals(o.getString("status")))&&(o.getJSONObject("customer").optString("client").toLowerCase().contains(q)||String.valueOf(o.getLong("number")).contains(q)))out.put(o);}return out;}
 JSONArray history(String id)throws Exception{JSONArray out=new JSONArray();for(int i=events.length()-1;i>=0;i--){JSONObject e=events.getJSONObject(i);if(id.equals(e.optString("order_id")))out.put(e);}return out;}
 JSONObject status(String id,int revision,String status,String comment)throws Exception{if(!java.util.Arrays.asList("new","confirmed","in_progress","completed","rejected").contains(status))throw new Exception("Կառավարչի անթույլատրելի կարգավիճակ");JSONObject o=find(id);if(o.getInt("revision")!=revision)throw new Exception("Տարբերակների անհամապատասխանություն։ Վերաբացեք պատվերը։");if("received".equals(o.optString("status")))throw new Exception("Ստացված պատվերը չի խմբագրվում");if(!o.optString("status").equals(status)||!o.optString("comment").equals(comment)){o.put("revision",revision+1).put("status",status).put("comment",comment).put("updated",java.time.Instant.now().toString());record(o,"order.updated","Կարգավիճակ՝ "+status);}return o;}
 void record(JSONObject o,String type,String description)throws JSONException {events.put(new JSONObject().put("sequence",nextEvent++).put("order_id",o.getString("id")).put("revision",o.getInt("revision")).put("event_type",type).put("occurred_at",java.time.Instant.now().toString()).put("description",description));}
}
